// Emits the frontend TS artifact: categories.ts for the payment-categories slice.
//
// Design: the generated file is SELF-CONTAINED and side-effect-free: types
// (slug union, entry), the ordered catalog array, the user-category default,
// and lookup helpers. UI components (design-layer ticket) resolve the icon
// name to a React component from shared/assets/icons.

const HEADER = `// Code generated by tools/payment-categories/generate.mjs from catalog.json. DO NOT EDIT.
`;

function tsStr(s) {
  return JSON.stringify(s);
}

export function emitFrontendTs(catalog) {
  const slugUnion = catalog.categories
    .map((cat) => `  | ${tsStr(cat.slug)}`)
    .join('\n');

  const entries = catalog.categories
    .map(
      (cat) =>
        `  { slug: ${tsStr(cat.slug)}, label: ${tsStr(cat.label)}, icon: ${tsStr(cat.icon)}, color: ${tsStr(cat.color)} },`,
    )
    .join('\n');

  return `${HEADER}
export type PaymentCategorySlug =
${slugUnion};

export type PaymentCategoryEntry = {
  readonly slug: PaymentCategorySlug;
  readonly label: string;
  readonly icon: string;
  readonly color: string;
};

export const paymentCategories: readonly PaymentCategoryEntry[] = [
${entries}
] as const;

// Дефолтный внешний вид пользовательской категории: одна иконка на серой
// подложке (решение карты «Платежи и операции» №4).
export const userCategoryDefault = {
  icon: ${tsStr(catalog.userCategoryDefault.icon)},
  color: ${tsStr(catalog.userCategoryDefault.color)},
} as const;

export function paymentCategoryBySlug(slug: string): PaymentCategoryEntry | undefined {
  return paymentCategories.find((entry) => entry.slug === slug);
}

export function isPaymentCategorySlug(slug: string): slug is PaymentCategorySlug {
  return paymentCategories.some((entry) => entry.slug === slug);
}
`;
}
